import assert from 'node:assert/strict';import {execFileSync} from 'node:child_process';import {readFileSync,writeFileSync} from 'node:fs';import {createHash} from 'node:crypto';
const git=(...a)=>execFileSync('git',a,{encoding:'utf8',timeout:30000}).trim();const blob=(sha,p)=>execFileSync('git',['show',sha+':'+p],{timeout:30000});const hash=b=>createHash('sha256').update(b).digest('hex');
const root='sandbox-release/harness-ui-toggle/',open='.github/sandbox-approvals/harness-ui-open.json',close='.github/sandbox-approvals/harness-ui-close.json';
