const diff=git('diff','--name-status',e.before,e.after);const match=/^[AM]\t(.+)$/.exec(diff);assert.ok(match);const path=match[1];assert.ok([open,close].includes(path));const markerBytes=blob(e.after,path);const m=JSON.parse(markerBytes);assert.equal(markerBytes.toString(),JSON.stringify(m)+'\n');assert.deepEqual(Object.keys(m).sort(),['authorization','from','parent','to']);assert.equal(m.parent,e.before);assert.equal(m.authorization,'APPROVE EXACT HARNESS UI BOOLEAN ONLY');assert.equal(typeof m.from,'boolean');assert.equal(typeof m.to,'boolean');assert.notEqual(m.from,m.to);assert.equal(m.to,path===open);
